mapper.insert:
        INSERT INTO shop
        	(
			shop_name
			,shop_num
			,telephone
			,shop_stat_ty_cd
			,lat
			,lot
			,c_name
			,c_num
			,fax
			,addr
        	)
        VALUES (
        	#{shopName}
        	, #{shopNum}
        	, #{telephone}
        	, #{shopStatTyCd}
        	, #{lat}
        	, #{lot}
        	,#{cName}
        	,#{cNum}
        	,#{fax}
        	,#{addr}
        	)

            SELECT LAST_INSERT_ID();

mapper.select:
SELECT COUNT(*)
FROM shop
WHERE shop_name=#{shopName}

mapper.update:
        UPDATE shop SET
        	shop_name 	= #{shopName}
			,telephone	= #{telephone}
			,shop_stat_ty_cd	= #{shopStatTyCd}
			,lat		= #{lat}
			,lot		= #{lot}
			,addr = #{addr}
			,fax = #{fax}
			,c_name = #{cName}
			,c_num = #{cNum}
        WHERE
        	shop_id 			= #{shopId}

mapper.select:
SELECT COUNT(*)
FROM
	shop_new_cstmr
WHERE
	shop_id=#{shopId}
	and join_date=#{joinDate}

mapper.update:
UPDATE shop_new_cstmr SET
	join_count=#{joinCount}
WHERE
	shop_id 			= #{shopId}
	AND join_date		= #{joinDate}

UPDATE shop set
	stamp_img_path=#{stampImgPath}
WHERE
	shop_id=#{shopId}
